def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    yesterday_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 200:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                yesterday_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # With supply 15-25 and req 13, at most one player can receive water each day.
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Need score: prioritize survival, especially after missed water.
    need = 0.0
    if hp <= 2:
        need += 1.0
    elif hp <= 4:
        need += 0.65
    elif hp <= 6:
        need += 0.35

    if no_water >= 2:
        need += 1.0
    elif no_water == 1:
        need += 0.45

    # Endgame urgency.
    if day >= 8:
        need += 0.2

    # Pressure from yesterday's market.
    pressure = 0.0
    if highest_prev >= 120:
        pressure += 0.45
    elif highest_prev >= 90:
        pressure += 0.3
    elif highest_prev >= 60:
        pressure += 0.15

    if avg_prev >= 90:
        pressure += 0.15
    elif avg_prev >= 60:
        pressure += 0.08

    if urgent_opp >= 2:
        pressure += 0.18
    elif urgent_opp == 1:
        pressure += 0.08

    if rich_opp >= 2:
        pressure += 0.1

    score = need + pressure + 0.55 * scarcity

    # Base conservative posture to outlast overbidders.
    if score < 0.35:
        bid = 12.0 + 10.0 * scarcity
    elif score < 0.75:
        bid = 24.0 + 18.0 * scarcity + 0.10 * highest_prev
    elif score < 1.2:
        bid = 42.0 + 20.0 * scarcity + 0.18 * highest_prev
    else:
        bid = 62.0 + 24.0 * scarcity + 0.24 * highest_prev

    # Tactical response to extreme prior overbids: don't chase unless necessary.
    if highest_prev >= 130 and hp > 3 and no_water == 0:
        bid = min(bid, 28.0 + 10.0 * scarcity)

    # If in danger, ensure competitiveness.
    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(0.92 * DAILY_SALARY + 20.0 * scarcity, budget))
    elif hp <= 4 or no_water == 1:
        bid = max(bid, 0.72 * DAILY_SALARY + 14.0 * scarcity)

    # Budget discipline.
    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days >= 3 and hp > 3:
        soft_cap = min(soft_cap, budget * 0.42)
    elif reserve_days >= 1 and hp > 2:
        soft_cap = min(soft_cap, budget * 0.58)

    bid = min(bid, soft_cap, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for k in opponents_status:
        o = opponents_status[k]
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        max_prev = 0.0
        avg_prev = 0.0

    # Base bid from supply pressure: higher supply -> lower need to outbid
    # supply in [15,25], WATER_REQ=9 => 1-2 units possible
    # If supply is near 15 (tight), bid more.
    tightness = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    tightness = max(0.0, min(1.0, tightness))

    # Urgency from my hp/no-water days
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    elif hp <= 4.0:
        urgency += 0.6
    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days == 1:
        urgency += 0.4

    # Opponent aggressiveness: if they were bidding around/above ~0.9*DAILY_SALARY, expect competition.
    opp_pressure = 0.0
    if avg_prev >= DAILY_SALARY * 0.9:
        opp_pressure = 1.0
    elif avg_prev >= DAILY_SALARY * 0.7:
        opp_pressure = 0.7
    elif avg_prev >= DAILY_SALARY * 0.5:
        opp_pressure = 0.4
    else:
        opp_pressure = 0.2

    # Decide target bid level
    # Keep below max_prev to avoid wasting money, but increase when tight/urgent.
    # Use a capped fraction of max_prev and salary.
    target = DAILY_SALARY * (0.45 + 0.25 * opp_pressure + 0.25 * tightness + 0.35 * urgency)

    if max_prev > 0.0:
        # If opponents previously spiked very high, only match a fraction.
        target = min(target, max_prev * (0.55 + 0.15 * urgency))

    # If supply allows two allocations (supply >= 18), reduce bid slightly.
    if supply >= 18.0:
        target *= 0.9

    # Ensure non-negative and do not exceed budget
    bid = max(0.0, min(budget, target))

    # If budget is tiny, still bid something to avoid death when urgent
    if bid <= 0.0 and urgency > 0.8:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.2))

    return float(bid)
